{
  "name": "bookmarks-app",
  "version": "1.0.0",
  "description": "Save and manage bookmarks — find them again, read-later, preserve copies.",
  "type": "module",
  "private": true,
  "scripts": {
    "start": "node server.js",
    "test": "node --test",
    "test:accept": "playwright test tests/acceptance.spec.mjs"
  },
  "dependencies": {
    "express": "4.21.2"
