import test from 'node:test';
import assert from 'node:assert/strict';
import { buildSearch } from '../src/query.js';

const items = [
  { title: 'Rome travel guide', description: 'Best trip in Italy', note: 'summer', url: 'http://a.com/rome', tags: ['travel', 'article'] },
  { title: 'Rome history book', description: 'ancient rome', note: '', url: 'http://b.com', tags: ['book', 'history'] },
  { title: 'Paris news', description: 'daily', note: 'read me', url: 'http://c.com', tags: ['news', 'travel'] },
  { title: 'AND circuits', description: 'logic gates', note: '', url: 'http://d.com', tags: ['newsletter'] },
];
const run = (q) => items.filter(buildSearch(q).pred).map((b) => b.title).sort();

test('plain search is case-insensitive substring across fields (SCN-006)', () => {
  assert.deepEqual(run('rome'), ['Rome history book', 'Rome travel guide']);
  assert.deepEqual(run('Rome'), ['Rome history book', 'Rome travel guide']);
  assert.deepEqual(run('read'), ['Paris news']); // matches note
  assert.deepEqual(run('nonsense'), []);
});

test('#tag is exact (SCN-007)', () => {
  assert.deepEqual(run('#news'), ['Paris news']);
  assert.deepEqual(run('news').sort(), ['AND circuits', 'Paris news']); // plain text is partial
});

test('implicit AND, OR, NOT, parentheses (SCN-007)', () => {
  assert.deepEqual(run('rome #travel'), ['Rome travel guide']);
  assert.deepEqual(run('rome AND #travel'), ['Rome travel guide']);
  assert.deepEqual(run('#book OR #news'), ['Paris news', 'Rome history book']);
  assert.deepEqual(run('rome (#article OR #book)'), ['Rome history book', 'Rome travel guide']);
  assert.deepEqual(run('rome NOT #travel'), ['Rome history book']);
});

test('quoted phrase and quoted operator as text (SCN-007)', () => {
  assert.deepEqual(run('"ancient rome"'), ['Rome history book']);
  assert.deepEqual(run('"AND"'), ['AND circuits']); // literal word, not the operator
});

test('empty query is inactive', () => {
  const s = buildSearch('');
  assert.equal(s.active, false);
  assert.equal(items.every(s.pred), true);
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { exportNetscape, parseNetscape } from '../src/netscape.js';

test('export produces standard format with title, tags, add_date (SCN-023)', () => {
  const html = exportNetscape([
    { url: 'http://a.com', title: 'Site A', description: 'desc', tags: ['x', 'y'], added: 1700000000000 },
  ]);
  assert.match(html, /<!DOCTYPE NETSCAPE-Bookmark-file-1>/);
  assert.match(html, /HREF="http:\/\/a\.com"/);
  assert.match(html, /ADD_DATE="1700000000"/);
  assert.match(html, /TAGS="x,y"/);
  assert.match(html, /Site A/);
  assert.match(html, /<DD>desc/);
});

test('round-trip preserves titles, tags, original dates (SCN-023)', () => {
  const items = [
    { url: 'http://a.com/p', title: 'A page', description: 'about a', tags: ['read', 'later'], added: 1690000000000 },
    { url: 'http://b.com', title: 'B', description: '', tags: [], added: 1695000000000 },
  ];
  const parsed = parseNetscape(exportNetscape(items));
  assert.equal(parsed.length, 2);
  assert.equal(parsed[0].url, 'http://a.com/p');
  assert.equal(parsed[0].title, 'A page');
  assert.deepEqual(parsed[0].tags, ['read', 'later']);
  assert.equal(parsed[0].added, 1690000000000);
  assert.equal(parsed[0].description, 'about a');
});

test('parses a browser-style export', () => {
  const html = `<!DOCTYPE NETSCAPE-Bookmark-file-1>
  <DL><p>
    <DT><A HREF="https://news.example.com" ADD_DATE="1600000000" TAGS="news,daily">Example News</A>
    <DT><A HREF="https://blog.example.com" ADD_DATE="1600000500">Blog</A>
  </DL><p>`;
  const parsed = parseNetscape(html);
  assert.equal(parsed.length, 2);
  assert.deepEqual(parsed[0].tags, ['news', 'daily']);
  assert.equal(parsed[1].title, 'Blog');
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { parseMeta } from '../src/metadata.js';

test('extracts title, description, and og:image for auto-fill (SCN-001)', () => {
  const html = `<html><head>
    <title>Serious Eats: Recipes</title>
    <meta name="description" content="Tested recipes and technique.">
    <meta property="og:image" content="/img/hero.jpg">
  </head><body></body></html>`;
  const meta = parseMeta(html, 'https://www.seriouseats.com/article');
  assert.equal(meta.title, 'Serious Eats: Recipes');
  assert.equal(meta.description, 'Tested recipes and technique.');
  assert.equal(meta.image, 'https://www.seriouseats.com/img/hero.jpg'); // resolved to absolute
});

test('prefers Open Graph title/description when present (SCN-001)', () => {
  const html = `<title>fallback</title>
    <meta property="og:title" content="OG Title">
    <meta property="og:description" content="OG description">`;
  const meta = parseMeta(html, 'https://example.com');
  assert.equal(meta.title, 'OG Title');
  assert.equal(meta.description, 'OG description');
});
